<script>
  import {onMount,tick} from 'svelte';
  import WindowControls from './WindowControls.svelte';
  import {calculatorWindow,calculatorDisplay,calculatorCapabilities} from './calculator-state.js';
  import {calculatorFormat} from './calculator-engine.js';
  import {CALCULATOR_UNITS,CALCULATOR_CATEGORIES} from './calculator-conversion.js';
  import {calculatorMenus} from './calculator-menus.js';
  import {createCalculatorNativeView,calculatorKeyboard,calculatorProgrammerReadout} from './calculator-native-view.js';
  import './calculator.css';
  let {state:calculatorData,profile,windowId,execute,registerView,available=true,active=true,controls={}}=$props();
  let root=$state(null),facade=$state(null),message=$state('');
  let originalState,originalProfile,originalWindowId,retired=false;
  const session=$derived(calculatorWindow(calculatorData,windowId));
  const cap=$derived(calculatorCapabilities(profile,session?.appId));
  const menuGroups=$derived(calculatorMenus({state:calculatorData,profile,windowId}));
  const menu=$derived(menuGroups.find(group=>group.id===session?.menu));
  const readout=$derived(session?.mode==='programmer'?calculatorProgrammerReadout(session):null);
  const display=$derived(calculatorDisplay(session));
  const scientific=$derived(session?.mode==='scientific');
  const functions=$derived(session?.second?[['square','x²'],['cube','x³'],['cbrt','∛x'],['exp','eˣ'],['asin','sin⁻¹'],['acos','cos⁻¹'],['atan','tan⁻¹'],['sinh','sinh'],['cosh','cosh'],['tanh','tanh'],['abs','|x|'],['ceil','ceil']]:[['square','x²'],['cube','x³'],['sqrt','√x'],['reciprocal','1/x'],['ln','ln'],['log','log₁₀'],['sin','sin'],['cos','cos'],['tan','tan'],['exp','eˣ'],['!','x!'],['floor','floor']]);
  const basicKeys=$derived(cap.windows?['%','clearEntry','clear','backspace','reciprocal','square','sqrt','/','7','8','9','*','4','5','6','-','1','2','3','+','sign','0','.','equals']:['clear','sign','%','/','7','8','9','*','4','5','6','-','1','2','3','+','0','.','equals']);
  const labels={clear:'AC',clearEntry:'CE',backspace:'⌫',reciprocal:'1/x',square:'x²',sqrt:'√x','/':'÷','*':'×','-':'−','sign':'+/−',equals:'=',AND:'AND',OR:'OR',XOR:'XOR',NOT:'NOT',MOD:'mod','<<':'<<','>>':'>>'};
  function current(){return !retired&&root?.isConnected&&calculatorData===originalState&&profile===originalProfile&&windowId===originalWindowId;}
  async function command(suffix,payload={}){if(!current()||!available||!active)return;const owner=root,response=await execute(`calculator.${suffix}`,{windowId},payload);if(current()&&root===owner)message=response?.status==='applied'?'':response?.error?.message??'The local calculator operation is unavailable.';return response;}
  async function menuAction(item){if(!item.enabled||!item.request||!current())return;const response=await execute(item.request.command,item.request.target,item.request.payload);if(current()){message=response?.status==='applied'?'':response?.error?.message??'The native menu operation is unavailable.';if(response?.status==='applied'&&session?.menu)command('sheet',{menu:null});}}
  async function conversion(payload){const response=await command('conversion',payload);if(response?.status==='applied'&&session?.conversion.input)command('convert');}
  function keyboard(event){if(!current()||!available||!active)return;if(session?.sheet||session?.menu){if(event.key==='Escape'){event.preventDefault();command('sheet',{sheet:null,menu:null});}return;}if(event.target.matches('input,select,textarea')){if(event.key==='Enter'&&event.target.dataset.calculatorControl==='expression'){event.preventDefault();command('evaluate');}return;}const request=calculatorKeyboard(event,session,profile);if(request){event.preventDefault();command(request.command,request.payload);}}
  function disabledDigit(key){return session?.mode==='programmer'&&(key==='.'||/^\d$/u.test(key)&&Number(key)>=session.base||/^[A-F]$/u.test(key)&&session.base!==16);}
  onMount(()=>{originalState=calculatorData;originalProfile=profile;originalWindowId=windowId;facade=createCalculatorNativeView({getRoot:()=>root,getState:()=>calculatorData,getProfile:()=>profile,windowId,available:()=>current()&&available&&active,tick});registerView?.(windowId,facade);return()=>{retired=true;facade.destroy();registerView?.(originalWindowId,null,facade);};});
</script>

<section bind:this={root} class="calculator-app" class:windows={cap.windows} class:classic={cap.classic} class:golden={cap.golden} class:scientific class:programmer={session?.mode==='programmer'} class:inactive={!active} data-calculator-window-id={windowId} data-profile={profile.id} role="region" aria-label={cap.label} tabindex="0" onkeydown={keyboard}>
 {#if session}
 <header class="calculator-titlebar">
  {#if !cap.windows}<WindowControls active={active} onclose={()=>command('window.close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} onsplitbegin={controls.onsplitbegin} onsplitside={controls.onsplitside} ongreenmenu={controls.ongreenmenu} fullScreen={controls.fullScreen} revealedTop={controls.revealedTop} modernGreenMenu={controls.modernGreenMenu} zoomed={controls.zoomed}/>{/if}
  <span>{cap.label}{session.appId!=='calculator'?' · installed local app':''}</span>
  <button data-calculator-control="help" aria-label="Calculator Help" onclick={()=>command('sheet',{sheet:'help',menu:null})}>?</button>
 </header>
 <div class="calculator-main" inert={!available||!active||!!session.sheet}>
  <div class="calculator-toolbar">
   <button class="calculator-mode" data-calculator-control="modeMenu" aria-label="Choose calculator mode" aria-expanded={session.menu==='view'} onclick={()=>command('sheet',{menu:session.menu==='view'?null:'view'})}>{cap.windows?'☰':'▦'} <strong>{session.mode==='basic'&&cap.windows?'Standard':session.mode[0].toUpperCase()+session.mode.slice(1)}</strong></button>
   <button data-calculator-control="tapeToggle" title={cap.windows?'History / local Paper Tape':'Docked Paper Tape · local equivalent'} aria-pressed={session.panel==='tape'} onclick={()=>command('panel',{panel:session.panel==='tape'?'none':'tape'})}>◷</button>
  </div>
  {#if session.appId!=='calculator'||cap.golden}<p class="calculator-qualification">{session.appId!=='calculator'?'Installed fictional local application · ':''}{cap.golden?'Tahoe26 visual proxy; no verified native27 pixels':''}</p>{/if}
  <nav class="calculator-local-menus" aria-label="Calculator menus">{#each menuGroups.filter(group=>group.id!=='calculator') as group}<button data-calculator-control={`menu:${group.id}`} disabled={!group.enabled} aria-expanded={session.menu===group.id} onclick={()=>command('sheet',{menu:session.menu===group.id?null:group.id})}>{group.label}</button>{/each}</nav>
  {#if menu}<div class="calculator-menu" role="menu" aria-label={menu.label}>{#each menu.children as item}{#if item.children}<details><summary>{item.label}</summary>{#each item.children as child}<button role="menuitemradio" aria-checked={!!child.checked} disabled={!child.enabled} data-calculator-control={`menu:${child.id}`} onclick={()=>menuAction(child)}>{child.checked?'✓ ':''}{child.label}</button>{/each}</details>{:else}<button role={item.checked!==undefined?'menuitemcheckbox':'menuitem'} aria-checked={item.checked} disabled={!item.enabled} data-calculator-control={`menu:${item.id}`} onclick={()=>menuAction(item)}><span>{item.checked?'✓ ':''}{item.label}</span><kbd>{item.shortcut??''}</kbd></button>{/if}{/each}</div>{/if}
  <div class="calculator-workspace">
   <div class="calculator-machine">
    <div class="calculator-display" class:error={!!session.error}>
     <div class="calculator-expression-line" aria-label="Current calculation">{session.expression}{session.completed?' =':''}</div>
     <output data-calculator-control="display" aria-label="Calculator display" aria-live="polite" title={display}>{display}</output>
     {#if session.rpn}<div class="calculator-stack" aria-label="RPN stack">{#each session.stack.slice(-4).reverse() as value,index}<span>{index+1}: {calculatorFormat(value,{places:session.places,programmer:session.mode==='programmer',base:session.base,wordBits:session.wordBits})}</span>{/each}</div>{/if}
    </div>
    <div class="calculator-memory-bar" aria-label="Calculator memory">{#each [['clear','MC'],['recall','MR'],['add','M+'],['subtract','M−'],['store','MS']] as [operation,label]}<button data-calculator-control={`memory:${operation}`} disabled={['clear','recall'].includes(operation)&&!session.memory.length||!!session.error&&!['clear','recall'].includes(operation)} onclick={()=>command('memory',{operation})}>{label}</button>{/each}<button data-calculator-control="memory:show" aria-pressed={session.panel==='memory'} onclick={()=>command('panel',{panel:session.panel==='memory'?'none':'memory'})}>M⌄{session.memory.length?' •':''}</button></div>
    {#if !cap.windows}<p class="calculator-qualification">MS and the multi-register Memory panel are local extensions to the native memory register.</p>{/if}
    {#if scientific}<div class="calculator-scientific-settings"><button data-calculator-control="angle" onclick={()=>command('settings',{angle:session.angle==='degrees'?'radians':'degrees'})}>{session.angle==='degrees'?'Deg':'Rad'}</button><button class:pressed={session.second} data-calculator-control="second" aria-pressed={session.second} onclick={()=>command('settings',{second:!session.second})}>2nd</button><button data-calculator-control="rpn" aria-pressed={session.rpn} onclick={()=>command('settings',{rpn:!session.rpn})}>RPN{cap.windows?' · local':''}</button></div>{/if}
    {#if readout}<div class="calculator-radix" aria-label="Programmer bases">{#each readout.bases as radix}<button class:selected={session.base===radix.base} data-calculator-control={`base:${radix.base}`} onclick={()=>command('settings',{base:radix.base})}><strong>{radix.label}</strong><span>{radix.text}</span></button>{/each}<label>Word size <select data-calculator-control="wordBits" value={session.wordBits} onchange={event=>command('settings',{wordBits:Number(event.currentTarget.value)})}>{#each [8,16,32,64] as bits}<option value={bits}>{bits} bit</option>{/each}</select></label><span class="calculator-character">Unicode: {readout.character.codePointAt(0)<32?'Control character':readout.character}</span></div><div class="calculator-bit-grid" aria-label="Actual programmer bits">{#each readout.bits as bit}<button class:set={bit.set} data-calculator-control={`bit:${bit.index}`} title={`Bit ${bit.index}`} aria-label={`Bit ${bit.index}: ${bit.set?1:0}`} onclick={()=>command('bit',{index:bit.index})}><small>{bit.index}</small>{bit.set?'1':'0'}</button>{/each}</div>{/if}
    <div class="calculator-keyboard">
     {#if scientific}<div class="calculator-functions">{#each functions as [key,label]}<button data-calculator-control={`key:${key}`} title={key} onclick={()=>command('key',{key})}>{label}</button>{/each}{#each [['pi','π'],['e','e'],['^','xʸ'],['EE','EE'],['(','('],[')',')']] as [key,label]}<button data-calculator-control={`key:${key}`} title={key} onclick={()=>command('key',{key})}>{label}</button>{/each}</div>{/if}
     {#if readout}<div class="calculator-programmer-keys">{#each ['A','B','C','D','E','F','AND','OR','XOR','NOT','MOD','<<','>>','(',')'] as key}<button disabled={disabledDigit(key)} data-calculator-control={`key:${key}`} onclick={()=>command('key',{key})}>{labels[key]??key}</button>{/each}</div>{/if}
     <div class="calculator-numeric-keys">{#each basicKeys as key}<button class:operator={['/','*','-','+','equals'].includes(key)} class:equals={key==='equals'} class:zero={key==='0'&&!cap.windows} disabled={disabledDigit(key)||session.mode==='programmer'&&['%','reciprocal','square','sqrt'].includes(key)} data-calculator-control={`key:${key}`} aria-label={key==='equals'&&session.rpn?'Enter RPN stack':key} onclick={()=>command('key',{key})}>{key==='clear'&&cap.windows?'C':key==='equals'&&session.rpn?'enter':labels[key]??key}</button>{/each}</div>
    </div>
    {#if session.rpn}<div class="calculator-stack-controls">{#each [['swap','x↔y'],['up','Roll ↑'],['down','Roll ↓'],['drop','Drop'],['clear','Clear stack']] as [operation,label]}<button data-calculator-control={`stack:${operation}`} onclick={()=>command('stack',{operation})}>{label}</button>{/each}</div>{/if}
    <details class="calculator-expression-editor"><summary>Expression editor · local extension</summary><label>Expression <input data-calculator-control="expression" aria-label="Local calculator expression" maxlength="4096" spellcheck="false" value={session.expression} oninput={event=>command('expression',{text:event.currentTarget.value})}/></label><button data-calculator-control="evaluate" onclick={()=>command('evaluate')}>Calculate</button></details>
    {#if session.conversion.enabled}<section class="calculator-conversion" aria-label="Unit conversion"><header><strong>{session.conversion.category==='currency'?'Currency · fixed scene rates':'Convert Units'}</strong><button data-calculator-control="conversion:close" aria-label="Hide conversion" onclick={()=>command('conversion',{enabled:false})}>×</button></header><label>Category <select data-calculator-control="conversion:category" value={session.conversion.category} onchange={event=>conversion({category:event.currentTarget.value})}>{#each CALCULATOR_CATEGORIES as category}<option value={category}>{category[0].toUpperCase()+category.slice(1)}</option>{/each}</select></label><label>Value <input data-calculator-control="conversion:input" aria-label="Value to convert" maxlength="4096" value={session.conversion.input} oninput={event=>conversion({input:event.currentTarget.value})}/></label><div class="calculator-unit-pair"><select data-calculator-control="conversion:from" aria-label="From unit" value={session.conversion.from} onchange={event=>conversion({from:event.currentTarget.value})}>{#each CALCULATOR_UNITS[session.conversion.category] as unit}<option value={unit.id}>{unit.label}</option>{/each}</select><button data-calculator-control="conversion:swap" aria-label="Swap units" onclick={()=>conversion({swap:true})}>⇄</button><select data-calculator-control="conversion:to" aria-label="To unit" value={session.conversion.to} onchange={event=>conversion({to:event.currentTarget.value})}>{#each CALCULATOR_UNITS[session.conversion.category] as unit}<option value={unit.id}>{unit.label}</option>{/each}</select></div><button data-calculator-control="conversion:calculate" onclick={()=>command('convert')}>Convert</button>{#if session.conversion.category==='currency'}<p>Authored rates as of {new Date(calculatorData.rateTime).toISOString().slice(0,10)} · not market rates. USD1 = EUR0.92 / GBP0.79 / JPY148.5 / CAD1.36 / AUD1.52.</p>{/if}</section>{/if}
   </div>
   {#if session.panel!=='none'}<aside class="calculator-paper-panel"><header><strong>{session.panel==='memory'?'Memory':cap.windows?'History / local Paper Tape':'Paper Tape · docked local equivalent'}</strong><button data-calculator-control="panel:close" aria-label="Close paper tape or memory" onclick={()=>command('panel',{panel:'none'})}>×</button></header><div class="calculator-paper-list" data-calculator-area="tape">{#if session.panel==='tape'}{#each session.tape as row}<button class="calculator-tape-row" data-calculator-control={`tape:${row.id}`} onclick={()=>command('tape',{operation:'recall',rowId:row.id})}><span>{row.expression}</span><strong>= {calculatorFormat(row.value,{places:session.places,programmer:row.mode==='programmer',base:row.base,wordBits:row.wordBits})}</strong><small>{new Date(row.at).toISOString()} · {row.mode}</small></button>{/each}{#if !session.tape.length}<p>No calculations yet.</p>{/if}{:else}{#each session.memory as row}<div class="calculator-memory-row"><button data-calculator-control={`memory:recall:${row.id}`} onclick={()=>command('memory',{operation:'recall',rowId:row.id})}>{calculatorFormat(row.value,{places:session.places})}</button><button data-calculator-control={`memory:delete:${row.id}`} aria-label="Delete memory value" onclick={()=>command('memory',{operation:'delete',rowId:row.id})}>MC</button><button data-calculator-control={`memory:add:${row.id}`} onclick={()=>command('memory',{operation:'add',rowId:row.id})}>M+</button><button data-calculator-control={`memory:subtract:${row.id}`} onclick={()=>command('memory',{operation:'subtract',rowId:row.id})}>M−</button></div>{/each}{#if !session.memory.length}<p>There’s nothing saved in memory.</p>{/if}{/if}</div><footer>{#if session.panel==='tape'}<button data-calculator-control="tape:copy" disabled={!session.tape.length} onclick={()=>command('clipboard',{operation:'copyTape'})}>Copy</button><button data-calculator-control="tape:clear" disabled={!session.tape.length} onclick={()=>command('tape',{operation:'clear'})}>Clear</button>{:else}<button data-calculator-control="memory:clearAll" disabled={!session.memory.length} onclick={()=>command('memory',{operation:'clear'})}>Clear memory</button>{/if}</footer></aside>{/if}
  </div>
  <footer class="calculator-status" role="status">{message||session.status||session.error?.message||`${cap.windows?'Standard is immediate; Scientific uses precedence.':'Arithmetic uses operator precedence.'} Currency is fixed local fiction.`}</footer>
 </div>
 {#if session.sheet}<div class="calculator-help-backdrop"><section class="calculator-help" role="dialog" aria-modal="true" aria-label="Calculator Help"><h2>{cap.label} Help</h2><p>{cap.availability}</p><p>Use the numeric keypad or keyboard: +, −, *, /, %, parentheses, Enter, Escape and Backspace. Scientific mode adds powers, roots, factorial, logarithms and trigonometry, with Degrees or Radians. Programmer mode offers binary, octal, decimal and hex, signed8/16/32/64-bit words and genuine bit toggles. Negative values use two’s-complement representation in nondecimal bases.</p><p>Memory and the bounded128-row tape belong to this actual window. RPN offers a32-value stack; Enter pushes the entry, binary operators consume two operands, and x↔y/Roll/Drop manipulate real values. The tape is docked here rather than opening a historical separate native paper-tape window. The expression editor and independent multiple-window command are explicitly local extensions. History export uses the scene clipboard, not the host clipboard.</p><p>Physical conversion uses SI definitions, including exact affine Celsius/Fahrenheit and absolute-zero validation. Currency conversion uses fixed authored USD-relative rates at scene creation; no update button pretends to fetch rates. No Math Notes, Graphing, live rates or host accounts are simulated.</p><button data-calculator-control="help:done" onclick={()=>command('sheet',{sheet:null,menu:null})}>Done</button></section></div>{/if}
 {:else}<p class="calculator-missing" role="alert">The original canonical Calculator session is unavailable.</p>{/if}
</section>
